module exploding_kittens (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] N,\n    input [3:0] E,\n    input [3:0] D,\n    input [7:0] e_pos_0,\n    input [7:0] e_pos_1,\n    input [7:0] e_pos_2,\n    input [7:0] e_pos_3,\n    input [7:0] e_pos_4,\n    input [7:0] e_pos_5,\n    input [7:0] e_pos_6,\n    input [7:0] e_pos_7,\n    input [7:0] d_pos_0,\n    input [7:0] d_pos_1,\n    input [7:0] d_pos_2,\n    input [7:0] d_pos_3,\n    input [7:0] d_pos_4,\n    input [7:0] d_pos_5,\n    input [7:0] d_pos_6,\n    input [7:0] d_pos_7,\n    output reg [7:0] winner,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] INIT = 3'b001;\n    localparam [2:0] LOOP = 3'b010;\n    localparam [2:0] PROCESS = 3'b011;\n    localparam [2:0] NEXT_PLAYER = 3'b100;\n    localparam [2:0] NEXT_POS = 3'b101;\n    localparam [2:0] FINISH = 3'b110;\n\n    reg [2:0] state, next_state;\n    reg [7:0] current_position;\n    reg [7:0] max_position;\n    reg [2:0] current_player;\n    reg [3:0] alive_count;\n    reg [2:0] hand_total [0:7];\n    reg [2:0] hand_defuse [0:7];\n    reg [0:7] alive;\n\n    integer i;  // Loop variable\n\n    // Card detection\n    reg is_exploding, is_defuse;\n    always @(*) begin\n        is_exploding = 1'b0;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < E) begin\n                case(i)\n                    0: if (e_pos_0 == current_position) is_exploding = 1'b1;\n                    1: if (e_pos_1 == current_position) is_exploding = 1'b1;\n                    2: if (e_pos_2 == current_position) is_exploding = 1'b1;\n                    3: if (e_pos_3 == current_position) is_exploding = 1'b1;\n                    4: if (e_pos_4 == current_position) is_exploding = 1'b1;\n                    5: if (e_pos_5 == current_position) is_exploding = 1'b1;\n                    6: if (e_pos_6 == current_position) is_exploding = 1'b1;\n                    7: if (e_pos_7 == current_position) is_exploding = 1'b1;\n                endcase\n            end\n        end\n\n        is_defuse = 1'b0;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < D) begin\n                case(i)\n                    0: if (d_pos_0 == current_position) is_defuse = 1'b1;\n                    1: if (d_pos_1 == current_position) is_defuse = 1'b1;\n                    2: if (d_pos_2 == current_position) is_defuse = 1'b1;\n                    3: if (d_pos_3 == current_position) is_defuse = 1'b1;\n                    4: if (d_pos_4 == current_position) is_defuse = 1'b1;\n                    5: if (d_pos_5 == current_position) is_defuse = 1'b1;\n                    6: if (d_pos_6 == current_position) is_defuse = 1'b1;\n                    7: if (d_pos_7 == current_position) is_defuse = 1'b1;\n                endcase\n            end\n        end\n    end\n\n    // Next alive player search\n    reg [2:0] next_alive_idx;\n    always @(*) begin\n        next_alive_idx = current_player;\n        for (i = 1; i < 8; i = i + 1) begin\n            reg [2:0] candidate = current_player + i;\n            if (candidate >= N) candidate = candidate - N;\n            if (alive[candidate] == 1'b1) begin\n                next_alive_idx = candidate;\n                break;\n            end\n        end\n    end\n\n    // State register\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case(state)\n            IDLE: if (start) next_state = INIT;\n            INIT: next_state = LOOP;\n            LOOP: begin\n                if ((alive_count <= 4'd1) || (current_position > max_position))\n                    next_state = FINISH;\n                else\n                    next_state = PROCESS;\n            end\n            PROCESS: next_state = NEXT_PLAYER;\n            NEXT_PLAYER: next_state = NEXT_POS;\n            NEXT_POS: next_state = LOOP;\n            FINISH: next_state = FINISH;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            winner <= 8'hFF;\n            done <= 1'b0;\n            current_position <= 8'd0;\n            current_player <= 3'd0;\n            alive_count <= 4'd0;\n            max_position <= 8'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                hand_total[i] <= 3'd0;\n                hand_defuse[i] <= 3'd0;\n                alive[i] <= 1'b0;\n            end\n        end else begin\n            case(state)\n                INIT: begin\n                    done <= 1'b0;\n                    winner <= 8'hFF;\n                    current_position <= 8'd0;\n                    current_player <= 3'd0;\n                    alive_count <= N;\n                    max_position <= 8'd0;\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < N) begin\n                            alive[i] <= 1'b1;\n                            hand_total[i] <= 3'd0;\n                            hand_defuse[i] <= 3'd0;\n                        end else begin\n                            alive[i] <= 1'b0;\n                        end\n                    end\n                    for (i = 0; i < 8; i = i + 1) begin\n                        if (i < E) begin\n                            case(i)\n                                0: if (e_pos_0 > max_position) max_position <= e_pos_0;\n                                1: if (e_pos_1 > max_position) max_position <= e_pos_1;\n                                2: if (e_pos_2 > max_position) max_position <= e_pos_2;\n                                3: if (e_pos_3 > max_position) max_position <= e_pos_3;\n                                4: if (e_pos_4 > max_position) max_position <= e_pos_4;\n                                5: if (e_pos_5 > max_position) max_position <= e_pos_5;\n                                6: if (e_pos_6 > max_position) max_position <= e_pos_6;\n                                7: if (e_pos_7 > max_position) max_position <= e_pos_7;\n                            endcase\n                        end\n                        if (i < D) begin\n                            case(i)\n                                0: if (d_pos_0 > max_position) max_position <= d_pos_0;\n                                1: if (d_pos_1 > max_position) max_position <= d_pos_1;\n                                2: if (d_pos_2 > max_position) max_position <= d_pos_2;\n                                3: if (d_pos_3 > max_position) max_position <= d_pos_3;\n                                4: if (d_pos_4 > max_position) max_position <= d_pos_4;\n                                5: if (d_pos_5 > max_position) max_position <= d_pos_5;\n                                6: if (d_pos_6 > max_position) max_position <= d_pos_6;\n                                7: if (d_pos_7 > max_position) max_position <= d_pos_7;\n                            endcase\n                        end\n                    end\n                end\n\n                PROCESS: begin\n                    if (is_exploding) begin\n                        if (hand_defuse[current_player] > 3'd0) begin\n                            hand_defuse[current_player] <= hand_defuse[current_player] - 3'd1;\n                            hand_total[current_player] <= hand_total[current_player] - 3'd1;\n                        end else begin\n                            alive[current_player] <= 1'b0;\n                            alive_count <= alive_count - 4'd1;\n                        end\n                    end\n\n                    else if (is_defuse) begin\n                        hand_defuse[current_player] <= hand_defuse[current_player] + 3'd1;\n                        hand_total[current_player] <= hand_total[current_player] + 3'd1;\n                        if (hand_total[current_player] >= 3'd5) begin\n                            hand_total[current_player] <= 3'd5;\n                            if ((hand_total[current_player] - hand_defuse[current_player]) > 3'd0) begin\n                                // Do nothing - neutral card was discarded\n                            end else begin\n                                hand_defuse[current_player] <= hand_defuse[current_player] - 3'd1;\n                            end\n                        end\n                    end\n\n                    else begin\n                        hand_total[current_player] <= hand_total[current_player] + 3'd1;\n                        if (hand_total[current_player] >= 3'd5) begin\n                            hand_total[current_player] <= 3'd5;\n                            if ((hand_total[current_player] - hand_defuse[current_player]) > 3'd0) begin\n                                // Do nothing - neutral card was discarded\n                            end else begin\n                                hand_defuse[current_player] <= hand_defuse[current_player] - 3'd1;\n                            end\n                        end\n                    end\n                end\n\n                NEXT_PLAYER: begin\n                    current_player <= next_alive_idx;\n                end\n\n                NEXT_POS: begin\n                    current_position <= current_position + 1;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (alive_count == 4'd1) begin\n                        for (i = 0; i < 8; i = i + 1) begin\n                            if (alive[i]) winner <= i;\n                        end\n                    end\n                end\n\n                default: begin\n                    // Do nothing\n                end\n            endcase\n        end\n    end\nendmodule